import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String s = scanner.nextLine();
        if (s.length() > 1) {
            s = s.substring(0, 1) + s.substring(1, s.length() - 1).replace("dot", ".") + s.substring(s.length() - 1);
            s = s.substring(0, 1) + s.substring(1, s.length() - 1).replaceFirst("at", "@") + s.substring(s.length() - 1);
        }
        System.out.println(s);
        scanner.close();
    }
}
